# 7-kuran-i-kerim-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN KISSALARINDAN HAYATA: YENİDEN DİRİLME (BAKARA, 259)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kıssanın Başlangıcı ve Soru</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Mekan: Çatıları çökmüş, duvarları yıkılmış,</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ıssız ve harap olmuş bir şehir (Beytülmakdis).</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Yolcu (Salih Kul / Hz. Üzeyir): Bineği (eşeği)</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ve yanındaki yiyecek-içecekle şehre uğrar.</text>\n  <text x="40" y="182" font-size="11" font-weight="bold" fill="#1e40af">• Hayret ve Tefekkür Sorusu:</text>\n  <text x="40" y="200" font-size="11" fill="#1e40af">  "Allah bu harap şehri ölümünden sonra nasıl diriltir?"</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzyıllık Ölüm ve Yeniden Diriltiliş</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İlahi Uygulama: Yüce Allah o kimseyi tam</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  100 YIL (miete âmin) ölü hâlde bıraktı, sonra diriltti.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Soru: "Burada ne kadar kaldın?"</text>\n  <text x="375" y="160" font-size="11" fill="#334155">• Cevap: "Bir gün veya günün bir kısmı kadar."</text>\n  <text x="375" y="184" font-size="11" font-weight="bold" fill="#166534">• Gerçeğin Bildirilmesi:</text>\n  <text x="375" y="202" font-size="11" fill="#166534">  "Hayır, tam yüz yıl kaldın!"</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUR\'AN KISSALARINDAN HAYATA: YENİDEN DİRİLME (BAKARA, 259)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kıssanın Başlangıcı ve Soru</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Mekan: Çatıları çökmüş, duvarları yıkılmış,</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ıssız ve harap olmuş bir şehir (Beytülmakdis).</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Yolcu (Salih Kul / Hz. Üzeyir): Bineği (eşeği)</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ve yanındaki yiyecek-içecekle şehre uğrar.</text>\n  <text x="40" y="182" font-size="11" font-weight="bold" fill="#1e40af">• Hayret ve Tefekkür Sorusu:</text>\n  <text x="40" y="200" font-size="11" fill="#1e40af">  "Allah bu harap şehri ölümünden sonra nasıl diriltir?"</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzyıllık Ölüm ve Yeniden Diriltiliş</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İlahi Uygulama: Yüce Allah o kimseyi tam</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  100 YIL (miete âmin) ölü hâlde bıraktı, sonra diriltti.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Soru: "Burada ne kadar kaldın?"</text>\n  <text x="375" y="160" font-size="11" fill="#334155">• Cevap: "Bir gün veya günün bir kısmı kadar."</text>\n  <text x="375" y="184" font-size="11" font-weight="bold" fill="#166534">• Gerçeğin Bildirilmesi:</text>\n  <text x="375" y="202" font-size="11" fill="#166534">  "Hayır, tam yüz yıl kaldın!"</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KISSADAKİ OLAYLAR ARASI İLİŞKİ VE AKIL YÜRÜTME ZİNCİRİ</text>\n  <rect x="20" y="55" width="150" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="95" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Gözlem ve Soru</text>\n  <text x="32" y="106" font-size="10.5" fill="#334155">Yıkılmış şehri gören</text>\n  <text x="32" y="124" font-size="10.5" fill="#334155">yolcu dirilişin nasıl</text>\n  <text x="32" y="142" font-size="10.5" fill="#334155">olacağını merak eder.</text>\n  <rect x="190" y="55" width="150" height="165" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="265" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">2. Yüz Yıl Uyku</text>\n  <text x="202" y="106" font-size="10.5" fill="#334155">Allah onu 100 yıl</text>\n  <text x="202" y="124" font-size="10.5" fill="#334155">vücuduyla öldürür ve</text>\n  <text x="202" y="142" font-size="10.5" fill="#334155">yeniden diriltir.</text>\n  <rect x="360" y="55" width="150" height="165" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="435" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">3. Üç Somut Delil</text>\n  <text x="372" y="106" font-size="10.5" fill="#334155">Bozulmayan yiyecek,</text>\n  <text x="372" y="124" font-size="10.5" fill="#334155">dirilen kemikler ve</text>\n  <text x="372" y="142" font-size="10.5" fill="#334155">onarılmış şehir görülür.</text>\n  <rect x="530" y="55" width="150" height="165" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="605" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">4. Yakîn İman</text>\n  <text x="542" y="106" font-size="10.5" fill="#334155">"Biliyorum ki Allah</text>\n  <text x="542" y="124" font-size="10.5" fill="#334155">her şeye kadirdir"</text>\n  <text x="542" y="142" font-size="10.5" fill="#334155">diyerek secdeye varır.</text>\n  <text x="350" y="242" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Merak -&gt; Deneyim -&gt; Gözlemlenen Mucize -&gt; Sarsılmaz İman (Kalbi Tatmin)</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KISSADAKİ OLAYLAR ARASI İLİŞKİ VE AKIL YÜRÜTME ZİNCİRİ</text>\n  <rect x="20" y="55" width="150" height="165" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="95" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Gözlem ve Soru</text>\n  <text x="32" y="106" font-size="10.5" fill="#334155">Yıkılmış şehri gören</text>\n  <text x="32" y="124" font-size="10.5" fill="#334155">yolcu dirilişin nasıl</text>\n  <text x="32" y="142" font-size="10.5" fill="#334155">olacağını merak eder.</text>\n  <rect x="190" y="55" width="150" height="165" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="265" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">2. Yüz Yıl Uyku</text>\n  <text x="202" y="106" font-size="10.5" fill="#334155">Allah onu 100 yıl</text>\n  <text x="202" y="124" font-size="10.5" fill="#334155">vücuduyla öldürür ve</text>\n  <text x="202" y="142" font-size="10.5" fill="#334155">yeniden diriltir.</text>\n  <rect x="360" y="55" width="150" height="165" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="435" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">3. Üç Somut Delil</text>\n  <text x="372" y="106" font-size="10.5" fill="#334155">Bozulmayan yiyecek,</text>\n  <text x="372" y="124" font-size="10.5" fill="#334155">dirilen kemikler ve</text>\n  <text x="372" y="142" font-size="10.5" fill="#334155">onarılmış şehir görülür.</text>\n  <rect x="530" y="55" width="150" height="165" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="605" y="80" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">4. Yakîn İman</text>\n  <text x="542" y="106" font-size="10.5" fill="#334155">"Biliyorum ki Allah</text>\n  <text x="542" y="124" font-size="10.5" fill="#334155">her şeye kadirdir"</text>\n  <text x="542" y="142" font-size="10.5" fill="#334155">diyerek secdeye varır.</text>\n  <text x="350" y="242" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Merak -&gt; Deneyim -&gt; Gözlemlenen Mucize -&gt; Sarsılmaz İman (Kalbi Tatmin)</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KISSADAKİ İLAHİ DELİLLER VE HZ. İBRAHİM\'İN KUŞLARI (BAKARA, 260)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bakara 259\'daki İki Zıt Mucize</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Delil (Yiyecek ve İçecek): Normalde birkaç</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  günde bozulan incir/üzüm ve içecek, 100 yıl</text>\n  <text x="40" y="134" font-size="11" fill="#334155">  geçmesine rağmen hiç bozulmamıştır (lem yetesenneh).</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• 2. Delil (Eşeğin Kemikleri): Çürüyüp dağılmış</text>\n  <text x="40" y="176" font-size="11" fill="#334155">  kemikler gözünün önünde birleşip et giydirilerek</text>\n  <text x="40" y="194" font-size="11" fill="#334155">  yeniden canlandırılmıştır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Bakara 260: Hz. İbrahim ve Dört Kuş</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İstek: "Rabbim! Ölüleri nasıl dirilttiğini bana</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  göster ki kalbim mutmain olsun (huzur bulsun)."</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Uygulama: Dört kuş alıp kendine alıştırması,</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sonra parçalarını ayrı tepelere bırakıp çağırması</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  emredildi; kuşlar dirilip koşarak ona geldi.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Allah\'ın "Azîz" (Mutlak Güç) ve "Hakîm" Oluşu</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KISSADAKİ İLAHİ DELİLLER VE HZ. İBRAHİM\'İN KUŞLARI (BAKARA, 260)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bakara 259\'daki İki Zıt Mucize</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• 1. Delil (Yiyecek ve İçecek): Normalde birkaç</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  günde bozulan incir/üzüm ve içecek, 100 yıl</text>\n  <text x="40" y="134" font-size="11" fill="#334155">  geçmesine rağmen hiç bozulmamıştır (lem yetesenneh).</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• 2. Delil (Eşeğin Kemikleri): Çürüyüp dağılmış</text>\n  <text x="40" y="176" font-size="11" fill="#334155">  kemikler gözünün önünde birleşip et giydirilerek</text>\n  <text x="40" y="194" font-size="11" fill="#334155">  yeniden canlandırılmıştır.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Bakara 260: Hz. İbrahim ve Dört Kuş</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İstek: "Rabbim! Ölüleri nasıl dirilttiğini bana</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  göster ki kalbim mutmain olsun (huzur bulsun)."</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Uygulama: Dört kuş alıp kendine alıştırması,</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  sonra parçalarını ayrı tepelere bırakıp çağırması</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  emredildi; kuşlar dirilip koşarak ona geldi.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Allah\'ın "Azîz" (Mutlak Güç) ve "Hakîm" Oluşu</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YENİDEN DİRİLME (BA\'S) İNANCININ İNSAN HAYATINA ETKİSİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğadaki Diriliş Örnekleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kışın kuruyup ölen toprağın ve ağaçların</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ilkbaharda yağmurla yeniden canlanması.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Kuru bir tohumun toprağa düşüp filizlenerek</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  devasa bir ağaca dönüşmesi.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• İlk kez yoktan yaratan Allah için yeniden</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#166534">  yaratmak (diriltmek) çok daha kolaydır (Yasin, 79).</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hayata Yansıyan Ahlaki Sonuçlar</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Sorumluluk Bilinci: Yaptığı her iyilik ve</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  kötülüğün hesabını vereceğini bilir.</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Ümit ve Teselli: Ölümün bir yok oluş değil,</text>\n  <text x="375" y="160" font-size="11" fill="#334155">  ebedi hayata geçiş kapısı olduğunu kavrar.</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Adalet İnancı: Dünyada karşılıksız kalan</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#9d174d">  hakların ahirette tam tecelli edeceğine güvenir.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YENİDEN DİRİLME (BA\'S) İNANCININ İNSAN HAYATINA ETKİSİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Doğadaki Diriliş Örnekleri</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kışın kuruyup ölen toprağın ve ağaçların</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ilkbaharda yağmurla yeniden canlanması.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Kuru bir tohumun toprağa düşüp filizlenerek</text>\n  <text x="40" y="160" font-size="11" fill="#334155">  devasa bir ağaca dönüşmesi.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• İlk kez yoktan yaratan Allah için yeniden</text>\n  <text x="40" y="204" font-size="11" font-weight="bold" fill="#166534">  yaratmak (diriltmek) çok daha kolaydır (Yasin, 79).</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hayata Yansıyan Ahlaki Sonuçlar</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Sorumluluk Bilinci: Yaptığı her iyilik ve</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  kötülüğün hesabını vereceğini bilir.</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Ümit ve Teselli: Ölümün bir yok oluş değil,</text>\n  <text x="375" y="160" font-size="11" fill="#334155">  ebedi hayata geçiş kapısı olduğunu kavrar.</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Adalet İnancı: Dünyada karşılıksız kalan</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#9d174d">  hakların ahirette tam tecelli edeceğine güvenir.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TECVİT UYGULAMASI: SAKİN MİM (MÎM-İ SAKİN) VE 3 HÂLİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. İhfa-i Şefevi (B Harfi)</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="35" y="116" font-size="11" font-weight="bold" fill="#1e40af">  harekeli "B" (ب) harfi gelirse</text>\n  <text x="35" y="134" font-size="11" fill="#334155">  dudak ihfası yapılır.</text>\n  <text x="35" y="160" font-size="11" fill="#334155">• Mim harfi dudaklar hafifçe</text>\n  <text x="35" y="178" font-size="11" fill="#334155">  değdirilip gunneli gizlenir.</text>\n  <text x="35" y="204" font-size="10.5" font-weight="bold" fill="#1d4ed8">Örnek: Termîhim bi-hicâratin</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn (M Harfi)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="260" y="116" font-size="11" font-weight="bold" fill="#166534">  harekeli "M" (م) harfi gelirse</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  idgam-ı misleyn meal-gunne olur.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• İki mim birleştirilerek şeddeli</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  ve 1,5 elif gunneli okunur.</text>\n  <text x="260" y="204" font-size="10.5" font-weight="bold" fill="#15803d">Örnek: Lehüm mâ yeşâûn</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. İzhar-ı Şefevi (Diğer 26 Harf)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="485" y="116" font-size="11" font-weight="bold" fill="#92400e">  "B" ve "M" dışında bir harf</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  gelirse dudak izharı yapılır.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Sakin mim gunne yapılmadan</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  açık ve net şekilde okunur.</text>\n  <text x="485" y="204" font-size="10.5" font-weight="bold" fill="#a16207">Örnek: Elhamdü / Lem yelid</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TECVİT UYGULAMASI: SAKİN MİM (MÎM-İ SAKİN) VE 3 HÂLİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. İhfa-i Şefevi (B Harfi)</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="35" y="116" font-size="11" font-weight="bold" fill="#1e40af">  harekeli "B" (ب) harfi gelirse</text>\n  <text x="35" y="134" font-size="11" fill="#334155">  dudak ihfası yapılır.</text>\n  <text x="35" y="160" font-size="11" fill="#334155">• Mim harfi dudaklar hafifçe</text>\n  <text x="35" y="178" font-size="11" fill="#334155">  değdirilip gunneli gizlenir.</text>\n  <text x="35" y="204" font-size="10.5" font-weight="bold" fill="#1d4ed8">Örnek: Termîhim bi-hicâratin</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn (M Harfi)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="260" y="116" font-size="11" font-weight="bold" fill="#166534">  harekeli "M" (م) harfi gelirse</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  idgam-ı misleyn meal-gunne olur.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• İki mim birleştirilerek şeddeli</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  ve 1,5 elif gunneli okunur.</text>\n  <text x="260" y="204" font-size="10.5" font-weight="bold" fill="#15803d">Örnek: Lehüm mâ yeşâûn</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. İzhar-ı Şefevi (Diğer 26 Harf)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Sakin mim\'den (مْ) sonra</text>\n  <text x="485" y="116" font-size="11" font-weight="bold" fill="#92400e">  "B" ve "M" dışında bir harf</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  gelirse dudak izharı yapılır.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Sakin mim gunne yapılmadan</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  açık ve net şekilde okunur.</text>\n  <text x="485" y="204" font-size="10.5" font-weight="bold" fill="#a16207">Örnek: Elhamdü / Lem yelid</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. TEMA BÜTÜNCÜL ÖZETİ: KUR\'AN-I KERİM\'İ OKUMAYA GİRİŞ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temada Öğrenilen Sure ve Ayetler</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Fatiha Suresi: Kur\'an\'ın açılış suresi (Ümmü\'l-Kitab);</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  hamd, tevhit ve sırat-ı müstakim duası içerir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Bakara Suresi 1-24. Ayetler: Müttakilerin, kâfirlerin</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ve münafıkların temel özellikleri anlatılır.</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• Bakara Suresi 259-260. Ayetler: Yeniden dirilme</text>\n  <text x="40" y="200" font-size="11" fill="#334155">  (Ba\'s) kıssası ve Allah\'ın diriltme kudreti işlenir.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Temada Öğrenilen Tecvit Kuralları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Med (Uzatma) Kuralları: Med harfleri (Elif, Vav, Ya),</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  Medd-i Tabii (1 elif), Medd-i Muttasıl ve Munfasıl.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Sakin Mim Kuralları: İhfa-i Şefevi (م + ب),</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  İdgam-ı Misleyn (م + م), İzhar-ı Şefevi (Diğer harfler).</text>\n  <text x="375" y="182" font-size="11" fill="#334155">• Tilavet Adabı: Abdestli olmak, Eûzü-Besmele çekmek,</text>\n  <text x="375" y="200" font-size="11" fill="#334155">  tertîl üzere (ağır ağır ve düşünerek) okumak.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. TEMA BÜTÜNCÜL ÖZETİ: KUR\'AN-I KERİM\'İ OKUMAYA GİRİŞ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Temada Öğrenilen Sure ve Ayetler</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Fatiha Suresi: Kur\'an\'ın açılış suresi (Ümmü\'l-Kitab);</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  hamd, tevhit ve sırat-ı müstakim duası içerir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Bakara Suresi 1-24. Ayetler: Müttakilerin, kâfirlerin</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ve münafıkların temel özellikleri anlatılır.</text>\n  <text x="40" y="182" font-size="11" fill="#334155">• Bakara Suresi 259-260. Ayetler: Yeniden dirilme</text>\n  <text x="40" y="200" font-size="11" fill="#334155">  (Ba\'s) kıssası ve Allah\'ın diriltme kudreti işlenir.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Temada Öğrenilen Tecvit Kuralları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Med (Uzatma) Kuralları: Med harfleri (Elif, Vav, Ya),</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  Medd-i Tabii (1 elif), Medd-i Muttasıl ve Munfasıl.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Sakin Mim Kuralları: İhfa-i Şefevi (م + ب),</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  İdgam-ı Misleyn (م + م), İzhar-ı Şefevi (Diğer harfler).</text>\n  <text x="375" y="182" font-size="11" fill="#334155">• Tilavet Adabı: Abdestli olmak, Eûzü-Besmele çekmek,</text>\n  <text x="375" y="200" font-size="11" fill="#334155">  tertîl üzere (ağır ağır ve düşünerek) okumak.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
